// Every function that takes `$` lives in this file: the engine follows `$`
// only into functions declared beside the hooks. Pure helpers are in ./lib;
// ./shared is the repo's shared/, copied in by scripts/sync-shared.sh.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { ChangedFile, CodexChoice, GateRun, Incoming, Proposal, ReaderDoc } from '../types'
import {
  CODEX_CONTEXT_TEXT,
  CONTEXT_TEXT,
  KIND_TITLES,
  PROPOSE_SPEC,
  REPORT_SPEC,
  REPORT_TRIES,
  SAVE_PROMPT,
  SAVE_SUGGEST_PERCENT,
  answerMessage,
  applyNumstat,
  capProposals,
  choiceLabel,
  clip,
  cockpitHeadline,
  compactInstructions,
  configChoice,
  declineMessage,
  diffArgv,
  effortLabel,
  failureMessage,
  fileLabel,
  filePathFor,
  gateLook,
  gateOutputOf,
  gateSummary,
  handoffKey,
  handoffOf,
  handoffSummary,
  isDiffOk,
  isGateCommand,
  isHandoff,
  isOpenProposal,
  isUnfinished,
  launchError,
  needsYou,
  openingPrompt,
  parseCodexEvent,
  parseModels,
  parsePorcelain,
  parseProposal,
  parseReport,
  planTitle,
  proposalArgv,
  proposalLook,
  settleChoice,
  settleCleared,
  settleInterrupted,
  splitDiff,
  splitLines,
  staleHandoffKeys,
  stepPosition,
  withSummaryAsk,
} from './lib'
import { AMBER, RED, toneColor } from './shared/colors'
import { drawFooter, mergeFooter } from './shared/footer'
import { STEP_ICONS } from './shared/glyphs'
import { rtl } from './shared/rtl'
import { bounded, cleanText, oneLine, pageBlocks, splitMarkdown, splitPlain, summarize } from './shared/text'
import { formatAge } from './shared/time'

const task = atom({ plugin: 'cockpit', key: 'task' } as const, '')
const note = atom({ plugin: 'cockpit', key: 'note' } as const, '')
const steps = atom({ plugin: 'cockpit', key: 'steps' } as const, [])
const files = atom({ plugin: 'cockpit', key: 'files' } as const, [])
const isFileListOpen = atom({ plugin: 'cockpit', key: 'isFileListOpen' } as const, false)
const isGitRepo = atom({ plugin: 'cockpit', key: 'isGitRepo' } as const, false)
const lastEditAt = atom({ plugin: 'cockpit', key: 'lastEditAt' } as const, 0)
const gate = atom({ plugin: 'cockpit', key: 'gate' } as const, null)
const gateOutput = atom({ plugin: 'cockpit', key: 'gateOutput' } as const, '')
const reader = atom({ plugin: 'cockpit', key: 'reader' } as const, null)
const isWorking = atom({ plugin: 'cockpit', key: 'isWorking' } as const, false)
const incoming = atom({ plugin: 'cockpit', key: 'incoming' } as const, null)
const hasSuggestedSave = atom({ plugin: 'cockpit', key: 'hasSuggestedSave' } as const, false)
const proposals = atom({ plugin: 'cockpit', key: 'proposals' } as const, [])
const models = atom({ plugin: 'cockpit', key: 'models' } as const, [])
const proposalChoice = atom({ plugin: 'cockpit', key: 'proposalChoice' } as const, { model: 'gpt-5.5', effort: 'medium' })

const PANE = 'cockpit'
const OPEN = { id: PANE, title: 'Cockpit' }
/** The person asked for it: bring the pane to the front (the surface may refuse the keys). */
const SHOW = { ...OPEN, focus: true as const }
const MAX_FILES = 15
/** Even opened, the list stops here: one drawn tree holds at most 100000 characters. */
const MAX_FILES_OPEN = 300
// Each mod has a reader of its own; the id never shows (the tab shows the title).
const READER = 'cockpit-reader'
const SENT_NOTE = 'בסוף הפרומפט נוספה ל-Codex בקשה לפתוח את התשובה בתקציר של 2–3 שורות.'
// The CLI inside the ChatGPT app tracks the account's models; the npm one can lag behind them.
const BUNDLED_CODEX = '/Applications/ChatGPT.app/Contents/Resources/codex-cli/CodexCLI.app/Contents/MacOS/codex'
/** Closed proposals kept below the open ones. */
const CLOSED_PROPOSALS = 3

let cwd = ''
let codexBinary = 'codex'
let isPumping = false
/** The repo's top folder: git's paths are relative to it, so its commands run there. */
let repoRoot = ''
/** The project a handoff belongs to: the repo's top folder, else the session's folder. */
let projectRoot = ''

// ── work state ───────────────────────────────────────────────────────────

/** Uncommitted changes from git, which also catches files a Bash command wrote. */
async function refreshFiles($: EngineInterface) {
  const top = await $.process.run(['git', 'rev-parse', '--show-toplevel'])
  if (top.exitCode !== 0 || !top.stdout.trim()) {
    await update($, isGitRepo, () => false)
    return
  }
  repoRoot = top.stdout.trim()
  await update($, isGitRepo, () => true)
  const status = await $.process.run(['git', 'status', '--porcelain=v1', '-z', '-uall'])
  if (status.exitCode !== 0) return
  let numstat = await $.process.run(['git', 'diff', '--numstat', '-z', 'HEAD'])
  if (numstat.exitCode !== 0) numstat = await $.process.run(['git', 'diff', '--numstat', '-z'])
  const list = applyNumstat(parsePorcelain(status.stdout), numstat.exitCode === 0 ? numstat.stdout : '')
  await update($, files, () => list)
  // Edits Claude's Edit and Write tools never saw (a Bash command, Codex) still make a passed
  // gate stale: the newest change on disk counts. A commit edits nothing, so it does not.
  let newest = 0
  for (const file of list.slice(0, MAX_FILES_OPEN)) {
    try {
      newest = Math.max(newest, (await $.fs.stat(`${repoRoot}/${file.path}`)).mtimeMs)
    } catch {
      // A deleted file has no time on disk.
    }
  }
  if (newest > (await read($, lastEditAt))) await update($, lastEditAt, () => newest)
}

async function clearWork($: EngineInterface) {
  await update($, task, () => '')
  await update($, note, () => '')
  await update($, steps, () => [])
}

/** The person cleared the task: nothing of it is handed to the next session. */
async function clearTask($: EngineInterface) {
  await clearWork($)
  try {
    const stored = await $.store.get(handoffKey(projectRoot))
    if (isHandoff(stored) && stored.sessionId === (await $.session.id())) {
      await $.store.set(handoffKey(projectRoot), { ...stored, isTaken: true })
    }
  } catch {
    // A handoff is a convenience: a store that fails costs nothing else.
  }
}

// ── handoff ──────────────────────────────────────────────────────────────

async function findProjectRoot($: EngineInterface): Promise<string> {
  try {
    const top = await $.process.run(['git', 'rev-parse', '--show-toplevel'])
    if (top.exitCode === 0 && top.stdout.trim()) return top.stdout.trim()
  } catch {
    // No git: the session's folder is the project.
  }
  return cwd
}

/** The work as it stands, kept for the next session in this project; only while there is any. */
async function saveHandoff($: EngineInterface, sessionId?: string) {
  if (!projectRoot) return
  const work = {
    task: await read($, task),
    note: await read($, note),
    steps: await read($, steps),
    files: await read($, files),
    gate: await read($, gate),
    lastEditAt: await read($, lastEditAt),
  }
  if (!work.task.trim() && work.steps.length === 0) return
  try {
    const id = sessionId ?? (await $.session.id())
    await $.store.set(handoffKey(projectRoot), handoffOf(work, id, projectRoot, await $.clock.now()))
  } catch {
    // A handoff is a convenience: a full store costs nothing else.
  }
}

/** Offers the previous session's unfinished work here; old ones go, and a reload changes nothing. */
async function loadIncoming($: EngineInterface) {
  try {
    const entries: [string, unknown][] = []
    for (const key of await $.store.keys()) {
      if (key.startsWith(handoffKey(''))) entries.push([key, await $.store.get(key)])
    }
    for (const key of staleHandoffKeys(entries, await $.clock.now())) await $.store.delete(key)
    const stored = await $.store.get(handoffKey(projectRoot))
    // A session with work of its own is offered no other: a reload must not put another
    // session's snapshot over the task under way here.
    const hasOwnWork = (await read($, task)).trim() !== '' || (await read($, steps)).length > 0
    const offered =
      !hasOwnWork && isHandoff(stored) && stored.sessionId !== (await $.session.id()) && !stored.isTaken && isUnfinished(stored)
        ? stored
        : null
    await update($, incoming, (previous): Incoming | null => {
      if (!offered) return null
      const isSame = previous && previous.at === offered.at && previous.sessionId === offered.sessionId
      return isSame ? previous : { ...offered, isQuiet: false }
    })
  } catch {
    await update($, incoming, () => null)
  }
}

/** Continue or ignore the previous session's work: either way it is not offered again. */
async function takeHandoff($: EngineInterface, choice: 'continue' | 'ignore') {
  const offered = await read($, incoming)
  if (!offered) return
  await update($, incoming, () => null)
  try {
    const stored = await $.store.get(handoffKey(offered.root))
    if (isHandoff(stored) && stored.at === offered.at) await $.store.set(handoffKey(offered.root), { ...stored, isTaken: true })
  } catch {
    // Taken in this session's view all the same.
  }
  if (choice === 'continue') {
    await fillPrompt($, openingPrompt(offered, await $.clock.now()), 'Handoff · פרומפט הפתיחה', offered.at)
  }
}

/** Puts text in the prompt box for the person to read and send; after a draft, below it. */
async function fillPrompt($: EngineInterface, text: string, title: string, at: number) {
  let isFilled = false
  try {
    const draft = (await $.prompt.read()).text
    const filled = await $.prompt.fill(draft.trim() ? { text: `\n\n${text}`, mode: 'append' } : { text, mode: 'replace' })
    isFilled = filled.isFilled
  } catch {
    isFilled = false
  }
  if (!isFilled) {
    const note = 'תיבת ה-prompt לא קיבלה את הטקסט — אפשר להעתיק אותו מכאן'
    await openReader($, { title, kind: 'markdown', text, note, noteTone: 'warn', at })
  }
}

/** The person saw the failed gate: it stops waiting for them, until the next run. */
async function dismissGate($: EngineInterface) {
  await update($, gate, run => (run ? { ...run, isDismissed: true } : run))
}

// ── the reader ───────────────────────────────────────────────────────────

/** Puts a text in the reader and opens it there, under the text's own title. */
async function openReader($: EngineInterface, doc: ReaderDoc) {
  const title = oneLine(doc.title) || 'קריאה'
  await update($, reader, () => ({ ...doc, title, page: 0 }))
  await $.ui.open({ id: READER, title, focus: true })
}

async function turnPage($: EngineInterface, by: number) {
  await update($, reader, doc => (doc ? { ...doc, page: Math.max(0, (doc.page ?? 0) + by) } : doc))
}

/** The last gate run's whole output; one Bash kept on disk is read from there. */
async function openGate($: EngineInterface) {
  const run = await read($, gate)
  if (!run) return
  let text = await read($, gateOutput)
  let note: string | undefined
  if (run.outputPath) {
    try {
      text = cleanText(String(await $.fs.read(run.outputPath)))
    } catch {
      note = `הפלט המלא לא נקרא (${run.outputPath}) — מוצג מה שנשמר`
    }
  }
  const title = run.isOk ? 'פלט השער · עבר' : 'פלט השער · נכשל'
  await openReader($, { title, kind: 'output', text, note, noteTone: 'warn', at: run.at })
}

/** A changed file's diff, fetched fresh each time it is opened. */
async function openDiff($: EngineInterface, file: ChangedFile) {
  const at = await $.clock.now()
  const title = `diff · ${file.path.split('/').pop() || file.path}`
  const fail = (note: string, text = '', noteTone?: 'failed') => openReader($, { title, kind: 'output', text, note, noteTone, at, file })
  const where = repoRoot ? { cwd: repoRoot } : undefined
  try {
    const head = await $.process.run(['git', 'rev-parse', '--verify', '-q', 'HEAD'], where)
    const argv = diffArgv(file, head.exitCode === 0)
    if (!argv) return await fail('אין diff — התיקייה לא ב-git')
    const ran = await $.process.run(argv, where)
    if (!isDiffOk(argv, ran.exitCode)) {
      return await fail(`✗ git diff נכשל (exit ${ran.exitCode}) — לחץ רענן כדי לנסות שוב`, ran.stderr || ran.stdout, 'failed')
    }
    const note = ran.isStdoutTruncated ? 'ה-diff ארוך מ-4MB — מוצג רק החלק הראשון' : undefined
    await openReader($, { title, kind: 'diff', text: ran.stdout, note, noteTone: 'warn', at, file })
  } catch (caught) {
    const reason = caught instanceof Error ? caught.message : String(caught)
    await fail(`✗ git לא רץ: ${reason} — לחץ רענן כדי לנסות שוב`, '', 'failed')
  }
}

function relative(path: string): string {
  return cwd && path.startsWith(`${cwd}/`) ? path.slice(cwd.length + 1) : path
}

// ── proposals to Codex ───────────────────────────────────────────────────

async function resolveCodexBinary($: EngineInterface) {
  try {
    await $.fs.stat(BUNDLED_CODEX)
    codexBinary = BUNDLED_CODEX
  } catch {
    codexBinary = 'codex'
  }
}

/** The models on offer, and the choice a proposal starts with: the last one approved, else config.toml's. */
async function loadModels($: EngineInterface) {
  const home = await $.env.get('HOME')
  if (!home) return
  let offered: ReturnType<typeof parseModels> = []
  try {
    offered = parseModels(await $.fs.read(`${home}/.codex/models_cache.json`))
  } catch {
    offered = []
  }
  let fromConfig: Partial<CodexChoice> = {}
  try {
    fromConfig = configChoice(await $.fs.read(`${home}/.codex/config.toml`))
  } catch {
    fromConfig = {}
  }
  let stored: Partial<CodexChoice> = {}
  try {
    stored = ((await $.store.get('proposalChoice')) as Partial<CodexChoice> | undefined) ?? {}
  } catch {
    stored = {}
  }
  await update($, models, () => offered)
  await update($, proposalChoice, () => settleChoice(offered, { ...fromConfig, ...stored }))
}

type CodexOutcome = { answer: string; error?: string }

/** One read-only Codex run, streamed, with the model and effort it was given. */
async function runCodexTurn($: EngineInterface, prompt: string, choice: CodexChoice): Promise<CodexOutcome> {
  let answer = ''
  let error: string | undefined
  let isDone = false
  let pending = ''
  let stderr = ''
  const handle = (line: string) => {
    const event = parseCodexEvent(line)
    if (event?.kind === 'message') answer = event.text
    if (event?.kind === 'error') error = event.message
    if (event?.kind === 'done') isDone = true
  }
  try {
    const stream = $.process.spawn({ argv: proposalArgv(codexBinary, withSummaryAsk(prompt), choice), cwd: cwd || undefined })
    for await (const chunk of stream) {
      if (chunk.stream === 'stderr') {
        stderr = (stderr + chunk.text).slice(-2000)
        continue
      }
      const { lines, rest } = splitLines(pending, chunk.text)
      pending = rest
      for (const line of lines) handle(line)
    }
    // A last event written without a newline still counts.
    if (pending.trim()) handle(pending)
  } catch (caught) {
    error = launchError(caught instanceof Error ? caught.message : String(caught))
  }
  if (!isDone && !error) error = clip(stderr.trim() || 'Codex נעצר בלי תשובה', 600)
  return { answer, error }
}

/** Moves a proposal out of `from` only; reports whether this caller made the move. */
async function moveProposal($: EngineInterface, id: number, from: Proposal['status'], change: Partial<Proposal>) {
  let isMoved = false
  await update($, proposals, list => {
    isMoved = false
    return list.map(p => {
      if (p.id !== id || p.status !== from) return p
      isMoved = true
      return { ...p, ...change }
    })
  })
  return isMoved
}

async function setProposal($: EngineInterface, id: number, change: Partial<Proposal>) {
  await update($, proposals, list => list.map(p => (p.id === id ? { ...p, ...change } : p)))
}

/** The model or effort for one waiting proposal; it settles to what the model offers. */
async function pickChoice($: EngineInterface, id: number, change: Partial<CodexChoice>) {
  const offered = await read($, models)
  const fallback = await read($, proposalChoice)
  await update($, proposals, list =>
    list.map(p => (p.id === id && p.status === 'pending' ? { ...p, choice: settleChoice(offered, { ...(p.choice ?? fallback), ...change }) } : p)),
  )
}

/** Approving freezes the proposal's choice; that choice is where the next proposal starts. */
async function approveProposal($: EngineInterface, id: number) {
  const offered = await read($, models)
  const fallback = await read($, proposalChoice)
  // Read and frozen in one update, so a pick landing beside the press is not lost.
  let choice = undefined as CodexChoice | undefined
  await update($, proposals, list => {
    choice = undefined
    return list.map(p => {
      if (p.id !== id || p.status !== 'pending') return p
      choice = settleChoice(offered, p.choice ?? fallback)
      return { ...p, status: 'approved' as const, choice }
    })
  })
  if (!choice) return
  await update($, proposalChoice, () => choice)
  try {
    await $.store.set('proposalChoice', choice)
  } catch {
    // The choice holds for this session all the same.
  }
}

async function declineProposal($: EngineInterface, id: number) {
  await moveProposal($, id, 'pending', { status: 'declined' })
}

/**
 * Hands text to Claude as a turn of its own. A hook may drop it without throwing;
 * either way the refusal is kept on the proposal and shown.
 */
async function deliver($: EngineInterface, id: number, text: string) {
  let reason: string | undefined
  try {
    const sent = await $.prompt.submit({ text })
    if (sent.drop !== undefined) reason = sent.drop || 'a hook dropped the prompt'
  } catch (caught) {
    reason = caught instanceof Error ? caught.message : String(caught)
  }
  if (reason === undefined) return
  await setProposal($, id, { deliveryError: reason })
  $.ui.toast(`התשובה של Codex לא הועברה ל-Claude (#${id}) — המלאה בפאנל Cockpit`)
}

async function runProposal($: EngineInterface, proposal: Proposal) {
  if (!(await moveProposal($, proposal.id, 'approved', { status: 'running' }))) return
  try {
    const choice = proposal.choice ?? (await read($, proposalChoice))
    const outcome = await runCodexTurn($, proposal.prompt, choice)
    // A /clear while it ran: the conversation it answers is gone, so it stays in the pane.
    const isCleared = (await read($, proposals)).find(p => p.id === proposal.id)?.isCleared === true
    if (outcome.error) {
      await setProposal($, proposal.id, { status: 'failed', answer: outcome.answer || outcome.error })
      if (!isCleared) await deliver($, proposal.id, failureMessage(proposal.id, outcome.error, outcome.answer))
    } else {
      await setProposal($, proposal.id, { status: 'done', answer: outcome.answer })
      $.ui.toast(`Codex ענה על הצעה #${proposal.id}`)
      if (!isCleared) await deliver($, proposal.id, answerMessage(proposal.id, proposal.kind, outcome.answer))
    }
  } catch (caught) {
    await setProposal($, proposal.id, {
      status: 'failed',
      answer: caught instanceof Error ? caught.message : String(caught),
    })
  }
}

/**
 * Tells Claude the person declined. Marked told only once the row is stored; a
 * hook's refusal is final, a call that threw is tried again a few times. Either
 * way the card says when Claude was not told.
 */
async function reportDecline($: EngineInterface, p: Proposal) {
  let refusal: string | undefined
  let isFinal = false
  try {
    const appended = await $.session.append({ message: { type: 'user', content: [{ type: 'text', text: declineMessage(p.id) }] } })
    if (appended.deny === undefined) {
      await setProposal($, p.id, { isReported: true })
      return
    }
    refusal = appended.deny || 'a hook refused the message'
    isFinal = true
  } catch (caught) {
    refusal = caught instanceof Error ? caught.message : String(caught)
  }
  const tries = (p.reportTries ?? 0) + 1
  if (isFinal || tries >= REPORT_TRIES) {
    await setProposal($, p.id, { isReported: true, reportTries: tries, deliveryError: refusal })
  } else {
    await setProposal($, p.id, { reportTries: tries })
  }
}

/**
 * The session's runner: a clock started at `session.start` calls it, so a Codex
 * run outlives the press that approved it. One run at a time.
 */
async function pump($: EngineInterface) {
  if (isPumping) return
  isPumping = true
  try {
    for (const p of await read($, proposals)) {
      if (p.status === 'declined' && !p.isReported) await reportDecline($, p)
    }
    const approved = (await read($, proposals)).find(p => p.status === 'approved')
    if (approved) await runProposal($, approved)
  } finally {
    isPumping = false
  }
}

// ── hooks ────────────────────────────────────────────────────────────────

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    cwd = e.cwd
    // State outlives a reload: an older gate run gets the fields it lacks; a reader of another shape goes.
    await update($, gate, (current): GateRun | null => {
      const old = current as Partial<GateRun> | null
      if (!old || typeof old.command !== 'string') return null
      return {
        ...(old as GateRun),
        summary: Array.isArray(old.summary) ? old.summary : [],
        isWhole: old.isWhole === true,
        isDismissed: old.isDismissed === true,
      }
    })
    await update($, isWorking, working => working === true)
    await update($, hasSuggestedSave, shown => shown === true)
    projectRoot = await findProjectRoot($)
    await loadIncoming($)
    await update($, reader, doc =>
      doc && typeof doc.text === 'string' && typeof doc.title === 'string' && typeof doc.kind === 'string' ? doc : null,
    )
    await $.command.register({ name: 'cockpit', description: 'Open the Cockpit pane: task, steps, files, gate' })
    await $.tool.register(REPORT_SPEC)
    await $.tool.register(PROPOSE_SPEC)
    await resolveCodexBinary($)
    await loadModels($)
    // A run a reload cut off ends: nothing runs it again, so it fails and Claude is told.
    let interrupted: number[] = []
    await update($, proposals, current => {
      const settled = settleInterrupted(Array.isArray(current) ? current : [])
      interrupted = settled.interrupted
      return settled.proposals
    })
    for (const id of interrupted) {
      await deliver($, id, failureMessage(id, 'the run was cut off when the Cockpit mod reloaded', ''))
    }
    void refreshFiles($)
    // Files change outside Claude's turns too (the person's editor, another session): look
    // again every half minute, and draw again, since the ages shown move with the clock.
    $.clock.every(30_000, async () => {
      await refreshFiles($)
      $.ui.invalidate('ui.render')
    })
    $.clock.every(1000, () => {
      void pump($)
    })
    void $.ui.open(OPEN)
    return next(e)
  })

  on('command.run', { command: 'cockpit' }, async $ => {
    await $.ui.open(SHOW)
    return { text: 'Cockpit פתוח.' }
  })

  // A sub-agent's run raises no turn.start; its turn.complete carries an agentId.
  on('turn.start', async ($, e, next) => {
    await update($, isWorking, () => true)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (!e.agentId) {
      await update($, isWorking, () => false)
      await saveHandoff($)
      void refreshFiles($)
    }
    return next(e)
  })

  // A session ends (exit, resume, /clear): its work is kept for the next one. After a
  // /clear no session.start comes, so the work is offered here at once and the pane cleared.
  // The whole chain shares a short bound: state and store writes only.
  on('session.end', async ($, e, next) => {
    await saveHandoff($, e.sessionId)
    if (e.reason === 'clear') {
      try {
        const stored = await $.store.get(handoffKey(projectRoot))
        if (isHandoff(stored) && !stored.isTaken && isUnfinished(stored)) {
          await update($, incoming, () => ({ ...stored, isQuiet: false }))
        }
      } catch {
        // Nothing to offer.
      }
      await clearWork($)
      await update($, hasSuggestedSave, () => false)
      await update($, proposals, current => settleCleared(Array.isArray(current) ? current : []))
    }
    return next(e)
  })

  // A compaction keeps the task and the plan word for word, and saves them first.
  on('session.compact', async ($, e, next) => {
    if (e.agentId) return next(e)
    await saveHandoff($)
    const extra = compactInstructions({ task: await read($, task), note: await read($, note), steps: await read($, steps) })
    if (!extra) return next(e)
    return next({ ...e, instructions: e.instructions ? `${e.instructions}\n\n${extra}` : extra })
  })

  // The person wrote something of their own: the handoff stops waiting for them.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'composer' || e.origin.kind === 'bridge') {
      const offered = await read($, incoming)
      if (offered && !offered.isQuiet) await update($, incoming, () => ({ ...offered, isQuiet: true }))
    }
    return next(e)
  })

  // Once per conversation, as the context fills: suggest saving what this session learned.
  // It counts only once shown: the box refuses while it holds text or a turn runs.
  on('session.measure', async ($, e, next) => {
    const percent = e.context.percent
    if (percent !== undefined && percent >= SAVE_SUGGEST_PERCENT && !(await read($, hasSuggestedSave))) {
      try {
        if ((await $.prompt.suggest({ text: SAVE_PROMPT })).isShown) await update($, hasSuggestedSave, () => true)
      } catch {
        // Tried again at the next measure.
      }
    }
    return next(e)
  })

  on('prompt.context', async ($, e, next) => {
    const result = await next(e)
    return {
      ...result,
      blocks: [...result.blocks, { name: 'cockpit', text: CONTEXT_TEXT }, { name: 'codex', text: CODEX_CONTEXT_TEXT }],
    }
  })

  // Proposing only queues a card; the person's press in the Cockpit pane is the approval.
  on('tool.check', { tool: 'mcp__cockpit__propose' }, () => ({ decision: 'allow' as const }))

  on('tool.call', { tool: 'mcp__cockpit__propose' }, async ($, e) => {
    const parsed = parseProposal(e as unknown as Record<string, unknown>)
    if (typeof parsed === 'string') return { deny: parsed }
    let id = 0
    // The default as it stands now is this proposal's own: a later approval does not move it.
    const choice = await read($, proposalChoice)
    await update($, proposals, current => {
      id = current.reduce((max, p) => Math.max(max, p.id), 0) + 1
      return capProposals([...current, { id, ...parsed, status: 'pending' as const, choice }])
    })
    $.ui.toast(`Claude מבקש לשלוח ל-Codex: ${KIND_TITLES[parsed.kind]}. האישור בפאנל Cockpit`)
    return {
      result:
        `Proposal #${id} is waiting for the user's approval in the Cockpit pane. Do not wait or poll: ` +
        "continue or end your turn. Codex's answer, or the user's decline, will reach you as a message.",
    }
  })

  // The report tool only updates this plugin's own pane, so it never needs a prompt.
  on('tool.check', { tool: 'mcp__cockpit__report' }, () => ({ decision: 'allow' as const }))

  on('tool.call', { tool: 'mcp__cockpit__report' }, async ($, e) => {
    const report = parseReport(e as unknown as Record<string, unknown>)
    if (report.task !== undefined) await update($, task, () => report.task ?? '')
    if (report.note !== undefined) await update($, note, () => report.note ?? '')
    if (report.steps !== undefined) await update($, steps, () => report.steps ?? [])
    // A task of its own here: the previous session's is no longer offered.
    if (report.task?.trim()) await update($, incoming, () => null)
    await saveHandoff($)
    return { result: 'Cockpit updated.' }
  })

  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit'] }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny !== undefined || ran.isError) return ran
    const editedAt = await $.clock.now()
    await update($, lastEditAt, () => editedAt)
    if (!(await read($, isGitRepo))) {
      const input = e as unknown as { file_path?: string; notebook_path?: string }
      const path = relative(input.notebook_path ?? input.file_path ?? '')
      const edited: ChangedFile = { path, status: 'ed', added: 0, removed: 0 }
      await update($, files, list => [...list.filter(f => f.path !== path), edited])
    }
    return ran
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    // Typed `unknown` where the engine's own declarations leave Bash's input loose.
    const command = String(e.command ?? '')
    if (ran.deny !== undefined || !isGateCommand(command)) return ran
    const output = ran.result as { backgroundTaskId?: string; interrupted?: boolean } | undefined
    if (output?.backgroundTaskId) return ran
    const isOk = ran.isError !== true && output?.interrupted !== true
    const kept = gateOutputOf(ran)
    const summary = gateSummary(kept.text, isOk)
    const isWhole = !kept.path && summary.join('\n') === kept.text.trim()
    await update($, gateOutput, () => kept.text)
    const ranAt = await $.clock.now()
    await update($, gate, () => ({
      command,
      isOk,
      at: ranAt,
      summary,
      isWhole,
      isDismissed: false,
      ...(kept.path ? { outputPath: kept.path } : {}),
    }))
    await saveHandoff($)
    return ran
  })

  on('tool.call', { tool: 'ExitPlanMode' }, async ($, e, next) => {
    const ran = await next(e)
    const plan = (ran.result as { plan?: string | null } | undefined)?.plan
    const title = ran.deny === undefined && plan ? planTitle(plan) : undefined
    if (title && !(await read($, task))) await update($, task, () => title)
    return ran
  })

  // The layout reads right to left: rows are `row-reverse`, columns hug the right
  // edge, and Hebrew runs are isolated as RTL (`rtl`).

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const table = $.ui.resolve(e)
    const { Box, Text, Button, Markdown } = table
    // Each surface's table may carry an element it then drops; decide by surface.
    const Select = e.surface !== 'mobile' && 'Select' in table ? table.Select : undefined
    const now = await $.clock.now()
    const columns = e.props.bodyColumns
    // A framed card gives up its border and padding.
    const cardColumns = Math.max(10, columns - 4)

    const heading = (text: string) => <Text bold>{rtl(text)}</Text>

    const currentTask = await read($, task)
    const currentNote = await read($, note)
    const stepList = await read($, steps)
    const fileList = await read($, files)
    const showAllFiles = await read($, isFileListOpen)
    const inGit = await read($, isGitRepo)
    const editedAt = await read($, lastEditAt)
    const lastGate = await read($, gate)
    const working = await read($, isWorking)
    const offered = await read($, incoming)
    const proposalList = await read($, proposals)
    const offeredModels = await read($, models)
    const defaultChoice = await read($, proposalChoice)
    const waitState = { isWorking: working, steps: stepList, gate: lastGate, incoming: offered, proposals: proposalList }
    const hero = cockpitHeadline(waitState)
    // A waiting proposal is always framed; the gate and the handoff are framed by what waits beside it.
    const waiting = needsYou({ ...waitState, proposals: [] })
    const position = stepPosition(stepList)
    const doneCount = stepList.filter(s => s.status === 'done').length
    const look = gateLook(lastGate, editedAt, now)
    const taskSummary = summarize(currentTask, { columns })
    const noteSummary = summarize(currentNote, { columns })
    const openProposals = proposalList.filter(isOpenProposal)
    const closedProposals = proposalList.filter(p => !isOpenProposal(p)).slice(-CLOSED_PROPOSALS)

    /** A press that opens `text` whole in the reader; none when the summary already is all of it. */
    const readAll = (key: string, title: string, text: string, isWhole: boolean, note?: string) =>
      isWhole ? null : (
        <Button key={key} label="קרא הכל" plain onPress={() => openReader($, { title, kind: 'markdown', text, note, at: now })} />
      )

    // One proposal's card: framed while it waits for the person, who picks the model and approves.
    const proposalCard = (p: Proposal) => {
      const status = proposalLook(p.status, { hasDeliveryError: Boolean(p.deliveryError), isCleared: p.isCleared })
      const isPending = p.status === 'pending'
      const width = isPending ? cardColumns : columns
      const choice = p.choice ?? defaultChoice
      const pickedModel = offeredModels.find(m => m.slug === choice.model)
      const prompt = summarize(p.prompt, { columns: width })
      return (
        <Box
          flexDirection="column"
          alignItems="flex-end"
          key={`proposal-${p.id}`}
          {...(isPending ? { borderStyle: 'round', borderColor: AMBER, paddingX: 1, width: '100%' } : {})}
        >
          <Box flexDirection="row-reverse" gap={1} flexWrap="wrap">
            <Text bold>{rtl(`#${p.id} ${KIND_TITLES[p.kind]}`)}</Text>
            <Text color={toneColor(status.tone)} dimColor={status.tone === 'muted'}>
              {rtl(status.text)}
            </Text>
            {!isPending && p.choice && p.status !== 'declined' && p.status !== 'cleared' ? (
              <Text dimColor>{rtl(`· ${choiceLabel(offeredModels, p.choice)}`)}</Text>
            ) : null}
          </Box>
          {p.why ? <Text wrap="wrap">{rtl(bounded(p.why, 1000))}</Text> : null}
          {isPending ? (
            <Box flexDirection="column" alignItems="flex-end">
              <Text dimColor>{rtl('הפרומפט שיישלח:')}</Text>
              <Markdown text={prompt.text} dimColor />
              {readAll(`read-prompt-${p.id}`, `#${p.id} · הפרומפט ל-Codex`, p.prompt, prompt.isWhole, SENT_NOTE)}
              {Select && offeredModels.length > 0 ? (
                <Box flexDirection="row-reverse" gap={2} flexWrap="wrap">
                  <Select
                    key={`proposal-model-${p.id}`}
                    label="מודל"
                    value={choice.model}
                    options={offeredModels.map(m => ({ value: m.slug, label: m.name }))}
                    onSelect={value => pickChoice($, p.id, { model: value })}
                  />
                  <Select
                    key={`proposal-effort-${p.id}`}
                    label="חשיבה"
                    value={choice.effort}
                    options={(pickedModel?.efforts ?? [choice.effort]).map(effort => ({
                      value: effort,
                      label: effortLabel(effort),
                    }))}
                    onSelect={value => pickChoice($, p.id, { effort: value })}
                  />
                </Box>
              ) : (
                <Text dimColor>{rtl(choiceLabel(offeredModels, choice))}</Text>
              )}
              <Box flexDirection="row-reverse" gap={1} flexWrap="wrap">
                <Button key={`pane-approve-${p.id}`} label="אשר ושלח ל-Codex" variant="primary" onPress={() => approveProposal($, p.id)} />
                <Button key={`pane-decline-${p.id}`} label="סרב" variant="secondary" onPress={() => declineProposal($, p.id)} />
              </Box>
            </Box>
          ) : (
            <Button
              key={`read-prompt-${p.id}`}
              label="הפרומפט שנשלח"
              plain
              onPress={() => openReader($, { title: `#${p.id} · הפרומפט ל-Codex`, kind: 'markdown', text: p.prompt, note: SENT_NOTE, at: now })}
            />
          )}
          {p.answer && (p.status === 'done' || p.status === 'failed') ? (
            <Box flexDirection="column" alignItems="flex-end">
              <Markdown text={summarize(p.answer, { columns }).text} dimColor />
              {readAll(`read-answer-${p.id}`, `#${p.id} · התשובה של Codex`, p.answer, summarize(p.answer, { columns }).isWhole)}
            </Box>
          ) : null}
          {p.deliveryError ? (
            <Text color={RED} wrap="wrap">
              {rtl(
                p.status === 'declined'
                  ? `${bounded(p.deliveryError, 500)} — Claude לא יודע שסירבת`
                  : `${bounded(p.deliveryError, 500)} — התשובה מוצגת כאן; אפשר להעתיק אותה ל-Claude`,
              )}
            </Text>
          ) : null}
        </Box>
      )
    }

    // The gate's lines; framed while a failure waits for the person, with a way to mark it handled.
    const isGateFramed = waiting === 'gate'
    const gateBody = (
      <Box
        flexDirection="column"
        alignItems="flex-end"
        {...(isGateFramed ? { borderStyle: 'round', borderColor: AMBER, paddingX: 1, width: '100%' } : {})}
      >
        <Text color={toneColor(look.tone)} dimColor={look.tone === 'muted'}>
          {rtl(look.text)}
        </Text>
        {lastGate ? (
          <Text dimColor wrap="truncate-end">
            {oneLine(lastGate.command, isGateFramed ? cardColumns : columns)}
          </Text>
        ) : null}
        {(lastGate?.summary ?? []).map(line => (
          <Text dimColor wrap="truncate-end">
            {line}
          </Text>
        ))}
        {lastGate ? (
          <Box flexDirection="row-reverse" gap={1} flexWrap="wrap">
            {!lastGate.isWhole ? <Button key="read-gate" label="קרא הכל" plain onPress={() => openGate($)} /> : null}
            {isGateFramed ? (
              <Button key="gate-dismiss" label="סמן כטופל" variant="secondary" onPress={() => dismissGate($)} />
            ) : null}
          </Box>
        ) : null}
      </Box>
    )

    return (
      <Box flexDirection="column" alignItems="flex-end" gap={1}>
        {/* The Hero: what is going on, in one line. */}
        <Text
          color={hero.tone === 'plain' ? undefined : toneColor(hero.tone)}
          dimColor={hero.tone === 'muted'}
          bold={hero.tone !== 'muted'}
          wrap="truncate-end"
        >
          {rtl(`${hero.glyph} ${hero.text}`)}
        </Text>

        {/* Proposals to Codex still open: waiting for the person, queued or running. */}
        {openProposals.length > 0 ? (
          <Box flexDirection="column" alignItems="flex-end" gap={1} width="100%">
            {heading('הצעות ל-Codex')}
            {openProposals.map(proposalCard)}
          </Box>
        ) : null}

        {/* A previous session's unfinished work: framed while it waits for the person. */}
        {offered ? (
          <Box
            flexDirection="column"
            alignItems="flex-end"
            {...(waiting === 'handoff' ? { borderStyle: 'round', borderColor: AMBER, paddingX: 1, width: '100%' } : {})}
          >
            <Text bold color={offered.isQuiet ? undefined : AMBER} dimColor={offered.isQuiet}>
              {rtl(`Handoff מהסשן הקודם · ${formatAge(offered.at, now)}`)}
            </Text>
            <Text wrap="wrap" dimColor={offered.isQuiet}>
              {rtl(handoffSummary(offered))}
            </Text>
            <Box flexDirection="row-reverse" gap={1} flexWrap="wrap">
              <Button key="handoff-continue" label="המשך מכאן" variant="secondary" onPress={() => takeHandoff($, 'continue')} />
              <Button
                key="handoff-read"
                label="קרא הכל"
                plain
                onPress={() =>
                  openReader($, { title: 'Handoff · פרומפט הפתיחה', kind: 'markdown', text: openingPrompt(offered, now), at: offered.at })
                }
              />
              <Button key="handoff-ignore" label="התעלם" plain onPress={() => takeHandoff($, 'ignore')} />
            </Box>
          </Box>
        ) : null}

        <Box flexDirection="column" alignItems="flex-end">
          <Box flexDirection="row-reverse" gap={1} alignItems="center" flexWrap="wrap">
            {heading('המשימה')}
            {currentTask || stepList.length > 0 ? (
              <Button key="clear" label="נקה משימה" variant="secondary" onPress={() => clearTask($)} />
            ) : null}
            <Button key="save-knowledge" label="שמור ידע" plain onPress={() => fillPrompt($, SAVE_PROMPT, 'שמור ידע', now)} />
          </Box>
          <Text dimColor={!currentTask} wrap="wrap">
            {rtl(taskSummary.text || 'אין משימה פעילה — Claude יעדכן כאן כשמשימה מתחילה')}
          </Text>
          {readAll('read-task', 'המשימה', currentTask, taskSummary.isWhole)}
          {currentNote ? (
            <Text color={AMBER} wrap="wrap">
              {rtl(noteSummary.text)}
            </Text>
          ) : null}
          {currentNote ? readAll('read-note', 'הערה', currentNote, noteSummary.isWhole) : null}
        </Box>

        {position ? (
          <Box flexDirection="column" alignItems="flex-end">
            <Box flexDirection="row-reverse" gap={1}>
              {heading('שלבים')}
              <Text dimColor>
                ({doneCount}/{stepList.length})
              </Text>
            </Box>
            {stepList.map(step => (
              <Text
                dimColor={step.status === 'done'}
                bold={step.status === 'doing' || step.status === 'blocked'}
                color={step.status === 'blocked' ? AMBER : undefined}
                wrap="wrap"
              >
                {rtl(`${STEP_ICONS[step.status]} ${bounded(step.text, 500)}`)}
              </Text>
            ))}
          </Box>
        ) : null}

        <Box flexDirection="column" alignItems="flex-end">
          <Box flexDirection="row-reverse" gap={1} alignItems="center">
            {heading('קבצים ששונו')}
            <Text dimColor>
              ({fileList.length}
              {inGit ? ' · git' : ''})
            </Text>
            <Button key="refresh" label="רענן" plain onPress={() => refreshFiles($)} />
          </Box>
          {fileList.length === 0 ? (
            <Text dimColor>{rtl(inGit ? 'אין שינויים' : 'אין שינויים — מחוץ ל-git מוצגים רק קבצים ש-Claude ערך')}</Text>
          ) : null}
          {fileList.slice(0, showAllFiles ? MAX_FILES_OPEN : MAX_FILES).map((file, i) => {
            const label = fileLabel(file.status)
            // Line counts are neither ok nor failed: they are drawn dim.
            const counts = file.added || file.removed ? `+${file.added} −${file.removed}` : ''
            const path = filePathFor(file.path, columns, label.length + counts.length + 4)
            return (
              <Box flexDirection="row-reverse" gap={1} flexWrap="wrap">
                <Text dimColor>{rtl(label)}</Text>
                {inGit ? (
                  <Button key={`file-${i}`} label={path} plain onPress={() => openDiff($, file)} />
                ) : (
                  <Text>{path}</Text>
                )}
                {counts ? <Text dimColor>{counts}</Text> : null}
              </Box>
            )
          })}
          {fileList.length > MAX_FILES ? (
            <Button
              key="files-more"
              label={showAllFiles ? 'הצג פחות' : `ועוד ${fileList.length - MAX_FILES}…`}
              plain
              onPress={() => update($, isFileListOpen, open => !open)}
            />
          ) : null}
          {showAllFiles && fileList.length > MAX_FILES_OPEN ? (
            <Text dimColor>{rtl(`מוצגים ${MAX_FILES_OPEN} קבצים; את השאר רואים ב-git status`)}</Text>
          ) : null}
        </Box>

        <Box flexDirection="column" alignItems="flex-end" width="100%">
          {heading('שער')}
          {gateBody}
        </Box>

        {/* The last few closed proposals, below the work; with none at all, what will show here. */}
        {closedProposals.length > 0 ? (
          <Box flexDirection="column" alignItems="flex-end" gap={1}>
            {heading('הצעות קודמות ל-Codex')}
            {closedProposals.map(proposalCard)}
          </Box>
        ) : openProposals.length === 0 ? (
          <Box flexDirection="column" alignItems="flex-end">
            {heading('הצעות ל-Codex')}
            <Text dimColor>{rtl('כאן יופיעו הצעות של Claude לשלוח ל-Codex, לאישורך')}</Text>
          </Box>
        ) : null}
      </Box>
    )
  })

  // The reader: the whole of one text a "read all" opened, split into blocks the
  // elements take; a diff is drawn as one, a command's output as plain code.
  on('ui.render', { component: 'Pane', requestId: 'cockpit-reader' }, async ($, e) => {
    const { Box, Text, Button, Markdown, Code } = $.ui.resolve(e)
    const doc = await read($, reader)
    if (!doc) {
      return (
        <Box flexDirection="column" alignItems="flex-end">
          <Text dimColor wrap="wrap">
            {rtl('כאן יופיע הטקסט המלא כשתלחץ "קרא הכל" בפאנל Cockpit.')}
          </Text>
        </Box>
      )
    }
    const now = await $.clock.now()
    const blocks = doc.kind === 'diff' ? splitDiff(doc.text) : doc.kind === 'output' ? splitPlain(doc.text) : splitMarkdown(doc.text)
    const pages = pageBlocks(blocks)
    const index = Math.min(doc.page ?? 0, Math.max(0, pages.length - 1))
    const file = doc.file
    // Above the page and again below it; keys differ, since a key is drawn once.
    const pager = (where: 'top' | 'end') =>
      pages.length > 1 ? (
        <Box flexDirection="row-reverse" gap={1} alignItems="center">
          <Text dimColor>{rtl(`עמוד ${index + 1} מתוך ${pages.length}`)}</Text>
          {index > 0 ? <Button key={`reader-prev-${where}`} label="הקודם" plain onPress={() => turnPage($, -1)} /> : null}
          {index < pages.length - 1 ? (
            <Button key={`reader-next-${where}`} label="הבא" plain onPress={() => turnPage($, 1)} />
          ) : null}
        </Box>
      ) : null
    return (
      <Box flexDirection="column" alignItems="flex-end" gap={1}>
        <Box flexDirection="row-reverse" gap={1} alignItems="center">
          <Text bold>{rtl(doc.title)}</Text>
          <Text dimColor>{rtl(formatAge(doc.at, now))}</Text>
          {file ? <Button key="reader-refresh" label="רענן" plain onPress={() => openDiff($, file)} /> : null}
        </Box>
        {file ? (
          <Text dimColor wrap="truncate-start">
            {file.path}
          </Text>
        ) : null}
        {doc.note ? (
          <Text
            color={doc.noteTone === 'failed' ? RED : doc.noteTone === 'warn' ? AMBER : undefined}
            dimColor={!doc.noteTone}
            wrap="wrap"
          >
            {rtl(doc.note)}
          </Text>
        ) : null}
        {blocks.length === 0 && !doc.note ? (
          <Text dimColor>{rtl(doc.kind === 'diff' ? 'אין שורות להציג — קובץ בינארי, או שהתוכן לא השתנה' : 'אין מה להציג')}</Text>
        ) : null}
        {pager('top')}
        <Box flexDirection="column" width="100%" gap={1}>
          {(pages[index] ?? []).map((block, i) =>
            doc.kind === 'markdown' ? (
              <Markdown key={`block-${i}`} text={block} />
            ) : (
              <Code key={`block-${i}`} source={block} format={doc.kind === 'diff' ? 'diff' : 'source'} />
            ),
          )}
        </Box>
        {pager('end')}
      </Box>
    )
  })

  // No band above the prompt: the line under it, beside the status line, holds a
  // button per mod (shared/footer.ts merges what the mods beneath drew there). What
  // waits for the person in the pane (a proposal, a failed gate, a blocked step) marks the button.
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const { Box, Button } = $.ui.resolve(e)
    const isWaiting =
      needsYou({
        isWorking: await read($, isWorking),
        steps: await read($, steps),
        gate: await read($, gate),
        incoming: await read($, incoming),
        proposals: await read($, proposals),
      }) !== undefined
    // Dim at rest; marked at full strength while something waits (this line drops `variant`).
    const button = (
      <Button
        key="open-cockpit"
        label={isWaiting ? '◆ Cockpit' : 'Cockpit'}
        plain
        dimColor={!isWaiting}
        onPress={() => $.ui.open(SHOW)}
      />
    )
    return drawFooter(Box, mergeFooter([button], await next(e)))
  })
}

