// Pure helpers: no `$`, so the tests import them directly.
import type {
  ChangedFile,
  CodexChoice,
  CodexModel,
  GateRun,
  Handoff,
  Incoming,
  Proposal,
  ProposalKind,
  Step,
  StepStatus,
} from '../types'
import type { Tone } from './shared/colors'
import { FAILED, IDLE, NEEDS_YOU, OK, RUNNING, STEP_ICONS, WARN } from './shared/glyphs'
import { TEXT_MAX, bounded, cleanText, cutLine, middleTruncate, oneLine } from './shared/text'
import { formatAge } from './shared/time'

/** Commands that count as a project gate (typecheck, lint, build, tests). */
const GATE = new RegExp(
  [
    String.raw`\b(npm|pnpm|yarn|bun)\s+(run\s+)?(lint|build|test|typecheck|check)\b`,
    String.raw`\bnpx\s+(tsc|eslint|vitest|jest|playwright)\b`,
    String.raw`(^|[\s;&|])tsc(\s|$)`,
    String.raw`\b(pytest|vitest|jest|eslint)\b`,
    String.raw`\bcompileall\b`,
    String.raw`\bclaude\s+plugin\s+(validate|test)\b`,
    String.raw`\bgate\.sh\b`,
  ].join('|'),
)

export function isGateCommand(command: string): boolean {
  const first = command.trimStart().split(/\s+/)[0] ?? ''
  if (['git', 'grep', 'rg', 'cat', 'echo', 'ls', 'head', 'tail'].includes(first)) return false
  return GATE.test(command)
}

/**
 * `git status --porcelain=v1 -z` → files, without line counts yet. NUL-separated,
 * so a path with spaces, quotes or Hebrew comes through as written; a rename's
 * original path follows it as an entry of its own.
 */
export function parsePorcelain(text: string): ChangedFile[] {
  const files: ChangedFile[] = []
  const entries = text.split('\0')
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i] ?? ''
    if (entry.length < 4) continue
    const status = entry.slice(0, 2)
    files.push({ path: entry.slice(3), status, added: 0, removed: 0 })
    if (status.includes('R') || status.includes('C')) i++
  }
  return files
}

/** Folds `git diff --numstat -z` counts into the porcelain list (a rename: counts, then old and new path). */
export function applyNumstat(files: ChangedFile[], text: string): ChangedFile[] {
  const counts = new Map<string, [number, number]>()
  const entries = text.split('\0')
  for (let i = 0; i < entries.length; i++) {
    const [added, removed, ...rest] = (entries[i] ?? '').split('\t')
    if (added === undefined || removed === undefined || rest.length === 0) continue
    let path = rest.join('\t')
    if (path === '') {
      // A rename: the old path, then the new one, each its own entry.
      path = entries[i + 2] ?? ''
      i += 2
    }
    counts.set(path, [Number(added) || 0, Number(removed) || 0])
  }
  return files.map(file => {
    const count = counts.get(file.path)
    return count ? { ...file, added: count[0], removed: count[1] } : file
  })
}

/** The plan's first `# ` heading, as a fallback task title. */
export function planTitle(plan: string): string | undefined {
  const match = /^#\s+(.+)$/m.exec(plan)
  return match?.[1]?.trim()
}

export const REPORT_TOOL = 'mcp__cockpit__report'

export const STEP_STATUSES: StepStatus[] = ['todo', 'doing', 'done', 'blocked']

export const REPORT_SPEC = {
