import type { BoxProps, ElementConstructor, RenderElement, RenderNode } from 'claude-code'

// The line under the prompt, beside the status line (the engine's `SessionMode`),
// is one drawing the mods share: what the engine draws there, then one button per
// mod that opens its pane. The engine asks the top mod, whose `next(e)` returns
// what the mods beneath drew; each mod adds its button to theirs and draws the
// whole line, so it reads the same in any load order.

/** The buttons' order, by key; a key not listed goes last. */
const BUTTON_ORDER = ['open-cockpit']

function keyOf(node: RenderNode): string | undefined {
  if (typeof node === 'string' || !('props' in node)) return undefined
  const key = (node.props as Record<string, unknown> | undefined)?.key
  return typeof key === 'string' ? key : undefined
}

function rank(node: RenderNode): number {
  const index = BUTTON_ORDER.indexOf(keyOf(node) ?? '')
  return index === -1 ? BUTTON_ORDER.length : index
}

/** The line's parts: what the engine (or another plugin) drew there, and the mods' buttons. */
export type FooterParts = { line: RenderNode[]; buttons: RenderNode[] }

/** This mod's buttons joined with the line the mods beneath drew. */
export function mergeFooter(mine: RenderNode[], below: RenderElement): FooterParts {
  const line: RenderNode[] = []
  const buttons = [...mine]
  if (below.type === 'Box' && keyOf(below) === 'footer') {
    for (const child of below.children ?? []) {
      if (keyOf(child) === 'footer-buttons' && typeof child !== 'string' && child.type === 'Box') {
        buttons.push(...(child.children ?? []))
      } else {
        line.push(child)
      }
    }
  } else {
    // The engine's own drawing (its mode labels), or another plugin's: kept whole.
    line.push(below)
  }
  return { line, buttons: buttons.sort((a, b) => rank(a) - rank(b)) }
}

/** The line as one row: what was there, then the buttons, right to left among themselves. */
export function drawFooter(Box: ElementConstructor<BoxProps>, parts: FooterParts): RenderElement {
  const buttons = Box({ key: 'footer-buttons', flexDirection: 'row-reverse', gap: 1, alignItems: 'center', children: parts.buttons })
  return Box({ key: 'footer', flexDirection: 'row', gap: 2, alignItems: 'center', children: [...parts.line, buttons] })
}

