files.types/index.d.ts:
export type StepStatus = 'todo' | 'doing' | 'done' | 'blocked'

export type Step = { text: string; status: StepStatus }

/** `status` is git's two-letter porcelain code, or `ed` for a file edited outside git. */
export type ChangedFile = { path: string; status: string; added: number; removed: number }

/** A gate run: `summary` is the up-to-three lines the pane shows; the whole output is `gateOutput`. */
export type GateRun = {
  command: string
  isOk: boolean
  at: number
  summary: string[]
  /** The summary is all the output said, so the pane offers no "read all". */
  isWhole: boolean
  /** Where Bash kept an output too large to hand back inline. */
  outputPath?: string
  /** The person marked this failure handled: it stops waiting for them. A new run starts unmarked. */
  isDismissed: boolean
}

/** How the reader draws a text: Markdown, a unified diff, or a command's plain output. */
export type ReaderKind = 'markdown' | 'diff' | 'output'

/** What the reader pane shows: the whole text a "read all" opened; `file` when it is a file's diff. */
export type ReaderDoc = {
  title: string
  kind: ReaderKind
  text: string
  note?: string
  /** A note that says something failed draws red; one that warns, amber. */
  noteTone?: 'warn' | 'failed'
  at: number
  file?: ChangedFile
  /** Which page is shown, from 0: a page holds as much as one drawn tree may. */
  page?: number
}

/** The last gate run as a handoff carries it: stale when files changed after it. */
export type HandoffGate = { command: string; isOk: boolean; isStale: boolean; at: number; summary: string[] }

/**
 * Where a session left its work, kept in the store per project (`handoff:<root>`) so
 * the next session there can pick it up. `isTaken` once continued or ignored.
 */
export type Handoff = {
  sessionId: string
  root: string
  at: number
  task: string
  note: string
  steps: Step[]
  /** Steps past the ones kept, and how many of them were not done. */
  omittedSteps?: number
  openOmittedSteps?: number
  files: { path: string; status: string }[]
  fileCount: number
  gate: HandoffGate | null
  isTaken?: boolean
}

/** A previous session's handoff shown in the pane; quiet once the person wrote something else. */
export type Incoming = Handoff & { isQuiet: boolean }

/** A model Codex offers this account, as its models cache lists it. */
export type CodexModel = { slug: string; name: string; efforts: string[]; defaultEffort: string }

/** Which model and reasoning effort a Codex run uses. */
export type CodexChoice = { model: string; effort: string }

export type ProposalKind = 'plan-review' | 'result-review' | 'question'

/** `cleared`: a /clear ended the conversation before it ran. */
export type ProposalStatus = 'pending' | 'approved' | 'running' | 'done' | 'declined' | 'failed' | 'cleared'

/** A prompt Claude wants to send to Codex, waiting for the person's approval. */
export type Proposal = {
  id: number
  kind: ProposalKind
  why: string
  prompt: string
  status: ProposalStatus
  /** The model and effort picked for this proposal; frozen once approved. */
  choice?: CodexChoice
  answer?: string
  /** A decline the runner has already told Claude about, or given up telling. */
  isReported?: boolean
  /** Failed tries at telling Claude about a decline. */
  reportTries?: number
  /** Why handing the answer (or the decline) to Claude failed, when it did. */
  deliveryError?: string
  /** A /clear came while it ran: its answer stays in the pane, not in the new conversation. */
  isCleared?: boolean
}

declare module 'claude-code' {
  interface PluginState {
    cockpit: {
      task: string
      note: string
      steps: Step[]
      files: ChangedFile[]
      isFileListOpen: boolean
      isGitRepo: boolean
      lastEditAt: number
      gate: GateRun | null
      /** Claude is in a turn of the main loop (`turn.start` to `turn.complete`). */
      isWorking: boolean
      /** A previous session's unfinished work, offered until continued or ignored. */
      incoming: Incoming | null
      /** "Save knowledge" was shown as a suggestion in this conversation; /clear starts it over. */
      hasSuggestedSave: boolean
      /** Claude's proposals to Codex: open ones, then the last few closed. */
      proposals: Proposal[]
      /** The models Codex offers this account. */
      models: CodexModel[]
      /** The model and effort a new proposal starts with: the last one approved. */
      proposalChoice: CodexChoice
      /** The last gate run's whole output; only the reader reads it. */
      gateOutput: string
      reader: ReaderDoc | null
    }
  }
}
